const API = "https://api.wheretheiss.at/v1/satellites/25544";

async function updateISS() {
  try {
    const response = await fetch(API);
    if (!response.ok) throw new Error(`ISS API replied ${response.status}`);
    const iss = await response.json();

    marker.setLatLng([iss.latitude, iss.longitude]);
    map.panTo([iss.latitude, iss.longitude]);
    document.querySelector("#info").textContent =
      `${iss.latitude.toFixed(2)}, ${iss.longitude.toFixed(2)}  |  ` +
      `${Math.round(iss.altitude)} km up  |  ${Math.round(iss.velocity)} km/h`;
  } catch (error) {
    console.error(error); // keep the old position and try again next time
  }
}

updateISS();
setInterval(updateISS, 5000); // every 5 seconds is kind to a free API

async function getPath() {
  const now = Math.floor(Date.now() / 1000);
  const times = [];
  for (let m = -45; m <= 90; m += 3) times.push(now + m * 60); // 45 min back, 90 ahead
  const points = [];
  for (let i = 0; i < times.length; i += 10) { // the API takes 10 times at once
    const batch = times.slice(i, i + 10).join(",");
    const reply = await fetch(`${API}/positions?timestamps=${batch}`);
    points.push(...(await reply.json()));
  }
  return points.map((p) => [p.latitude, p.longitude]);
}

// Start a new line whenever the path jumps across the map's edge.
function splitAtEdge(points) {
  const lines = [[]];
  points.forEach(([lat, lon], i) => {
    if (i > 0 && Math.abs(lon - points[i - 1][1]) > 180) lines.push([]);
    lines[lines.length - 1].push([lat, lon]);
  });
  return lines;
}

getPath().then((p) => L.polyline(splitAtEdge(p), { color: "#e0a33a" }).addTo(map));

// Once, next to the marker: a circle that starts empty.
const circle = L.circle([0, 0], { radius: 0, color: "#3b6fd4", weight: 1 }).addTo(map);

// Inside updateISS(), after marker.setLatLng(...):
circle.setLatLng([iss.latitude, iss.longitude]);
circle.setRadius((iss.footprint / 2) * 1000); // footprint is a width in km. Leaflet wants a radius in metres.

// iss.visibility says how to see it: "daylight" or "eclipsed" (in Earth's shadow).
document.querySelector("#info").textContent += `  |  ${iss.visibility}`;
